   111  static void LogPDPInfo(const PDBInfo *info)
   112  {
   113    (void) LogMagickEvent(CoderEvent,GetMagickModule(),
   114                          "PDP Info:\n"
   115                          "    name            : %.32s\n"
   116                          "    attributes      : %d\n"
   117                          "    version         : %d\n"
   118                          "    create_time     : %lu\n"
   119                          "    modify_time     : %lu\n"
   120                          "    archive_time    : %lu\n"
   121                          "    modify_number   : %lu\n"
   122                          "    application_info: %lu\n"
   123                          "    sort_info       : %lu\n"
   124                          "    type            : %.4s\n"
   125                          "    id              : %.4s\n"
   126                          "    seed            : %lu\n"
   127                          "    next_record     : %lu\n"
   128                          "    number_records  : %u",
   129                          info->name,
   130                          info->attributes,
   131                          info->version,
   132                          info->create_time,
   133                          info->modify_time,
   134                          info->archive_time,
   135                          info->modify_number,
   136                          info->application_info,
   137                          info->sort_info,
   138                          info->type,
   139                          info->id,
   140                          info->seed,
   141                          info->next_record,
   142                          info->number_records);
   143  }
