   145  static void LogPDPImage(const PDBImage *image)
   146  {
   147    static const char *type_string;
   148    switch(image->type)
   149      {
   150      case 0: type_string = "2 bit gray"; break;
   151      case 2: type_string = "4 bit gray"; break;
   152      default: type_string = "monochrome"; break;
