   154
   155    (void) LogMagickEvent(CoderEvent,GetMagickModule(),
   156                          "PDP Image:\n"
   157                          "    name:       %.32s\n"
   158                          "    version:    %d\n"
   159                          "    type:       %d (%s)\n"
   160                          "    reserved_1: %lu\n"
   161                          "    note:       %lu\n"
   162                          "    x_last:     %u\n"
   163                          "    y_last:     %u\n"
