   184  /*
   185  %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
   186  %                                                                             %
   187  %                                                                             %
   188  %                                                                             %
   189  %   D e c o d e I m a g e                                                     %
   190  %                                                                             %
   191  %                                                                             %
   192  %                                                                             %
   193  %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
   194  %
   195  %  Method DecodeImage unpacks the packed image pixels into runlength-encoded
   196  %  pixel packets.
   197  %
   198  %  The format of the DecodeImage method is:
   199  %
   200  %      unsigned int DecodeImage(Image *image,unsigned char *pixels,
   201  %        const size_t length)
   202  %
   203  %  A description of each parameter follows:
   204  %
   205  %    o status:  Method DecodeImage returns True if all the pixels are
   206  %      uncompressed without error, otherwise False.
   207  %
   208  %    o image: The address of a structure of type Image.
   209  %
   210  %    o pixels:  The address of a byte (8 bits) array of pixel data created by
   211  %      the decoding process.
   212  %
   213  %
   214  */
   215  static MagickPassFail DecodeImage(Image *image,unsigned char *pixels,
   216    const size_t length)
   217  {
   218    int
   219      c,
   220      count,
   280  %  Method IsPDB returns True if the image format type, identified by the
   281  %  magick string, is PDB.
   282  %
   283  %  The format of the ReadPDBImage method is:
   284  %
   285  %      unsigned int IsPDB(const unsigned char *magick,const size_t length)
   286  %
   287  %  A description of each parameter follows:
   288  %
   289  %    o status:  Method IsPDB returns True if the image format type is PDB.
   290  %
   291  %    o magick: This string is generally the first few bytes of an image file
   292  %      or blob.
   293  %
   294  %    o length: Specifies the length of the magick string.
   295  %
   296  %
   297  */
   298  static unsigned int IsPDB(const unsigned char *magick,const size_t length)
   299  {
   300    if (length < 68)
   301      return(False);
   302    if (memcmp(magick+60,"vIMGView",8) == 0)
   303      return(True);
   304    return(False);
   305  }
