   307  /*
   308  %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
   309  %                                                                             %
   310  %                                                                             %
   311  %                                                                             %
   312  %   R e a d P D B I m a g e                                                   %
   313  %                                                                             %
   314  %                                                                             %
   315  %                                                                             %
   316  %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
   317  %
   318  %  Method ReadPDBImage reads an Pilot image file and returns it.  It
   319  %  allocates the memory necessary for the new Image structure and returns a
   320  %  pointer to the new image.
   321  %
   322  %  The format of the ReadPDBImage method is:
   323  %
   324  %      Image *ReadPDBImage(const ImageInfo *image_info,ExceptionInfo *exception)
   325  %
   326  %  A description of each parameter follows:
   327  %
   328  %    o image:  Method ReadPDBImage returns a pointer to the image after
   329  %      reading. A null image is returned if there is a memory shortage or if
   330  %      the image cannot be read.
   331  %
   332  %    o image_info: Specifies a pointer to a ImageInfo structure.
   333  %
   334  %    o exception: return any errors or warnings in this structure.
   335  %
   336  %
   337  */
   338  #define ThrowPDBReaderException(code_,reason_,image_) \
   339  { \
   340    MagickFreeMemory(pixels);                   \
   341    ThrowReaderException(code_,reason_,image_); \
   342  }
   343
   344  static Image *ReadPDBImage(const ImageInfo *image_info,ExceptionInfo *exception)
   345  {
   346    char
   347      record_type,
   348      tag[3];
   349
   350    Image
   351      *image;
   352
   353    IndexPacket
   354      index;
   355
   356    long
   357      offset;
   358
   359    PDBImage
   360      pdb_image;
   361
   362    PDBInfo
   363      pdb_info;
   364
   365    register IndexPacket
   366      *indexes;
   367
   368    unsigned long
   369      y;
   370
   371    register unsigned long
   372      x;
   373
   374    register PixelPacket
   375      *q;
   376
   377    register unsigned char
   378      *p;
   379
   380    size_t
   381      count;
   382
   383    unsigned char
   384      *pixels = (unsigned char *) NULL;
   385
   386    unsigned int
   387      bits_per_pixel,
   388      status;
   389
   390    size_t
   391      packets;
   392
   393    /*
   394      Open image file.
   395    */
   396    assert(image_info != (const ImageInfo *) NULL);
   397    assert(image_info->signature == MagickSignature);
   398    assert(exception != (ExceptionInfo *) NULL);
   399    assert(exception->signature == MagickSignature);
   400    image=AllocateImage(image_info);
   401    status=OpenBlob(image_info,image,ReadBinaryBlobMode,exception);
   402    if (status == False)
   403      ThrowPDBReaderException(FileOpenError,UnableToOpenFile,image);
   404    /*
   405      Determine if this is a PDB image file.
   406    */
   407    count=ReadBlob(image,32,pdb_info.name);
   408    if (count != 32)
   409      ThrowPDBReaderException(CorruptImageError,ImproperImageHeader,image);
   410    pdb_info.name[sizeof(pdb_info.name)-1]='\0';
   411    pdb_info.attributes=ReadBlobMSBShort(image);
   412    pdb_info.version=ReadBlobMSBShort(image);
   413    pdb_info.create_time=ReadBlobMSBLong(image);
   414    pdb_info.modify_time=ReadBlobMSBLong(image);
   415    pdb_info.archive_time=ReadBlobMSBLong(image);
   416    pdb_info.modify_number=ReadBlobMSBLong(image);
   417    pdb_info.application_info=ReadBlobMSBLong(image);
   418    pdb_info.sort_info=ReadBlobMSBLong(image);
   419    (void) ReadBlob(image,4,pdb_info.type);
   420    (void) ReadBlob(image,4,pdb_info.id);
   421    pdb_info.seed=ReadBlobMSBLong(image);
   422    pdb_info.next_record=ReadBlobMSBLong(image);
   423    pdb_info.number_records=ReadBlobMSBShort(image);
   424    if (image->logging)
   425      LogPDPInfo(&pdb_info);
   426    if ((memcmp(pdb_info.type,"vIMG",4) != 0) ||
   427        (memcmp(pdb_info.id,"View",4) != 0))
   428      ThrowPDBReaderException(CorruptImageError,ImproperImageHeader,image);
   429    if (pdb_info.next_record != 0)
   430      ThrowPDBReaderException(CoderError,MultipleRecordListNotSupported,image);
   431    /*
   432      Read record header.
   433    */
   434    offset=(long) ReadBlobMSBLong(image);
   435    (void) ReadBlob(image,3,tag);
   436    record_type=ReadBlobByte(image);
   437    if (((record_type != 0x00) && (record_type != 0x01)) ||
   438        (memcmp(tag,"\x40\x6f\x80",3) != 0))
   439      ThrowPDBReaderException(CorruptImageError,CorruptImage,image);
   440    if ((offset-TellBlob(image)) == 6)
   441      {
   442        (void) ReadBlobByte(image);
   443        (void) ReadBlobByte(image);
   444      }
   445    if (pdb_info.number_records > 1)
   446      {
   447        offset=(long) ReadBlobMSBLong(image);
   448        (void) ReadBlob(image,3,tag);
   449        record_type=ReadBlobByte(image);
   450        if (((record_type != 0x00) && (record_type != 0x01)) ||
   451            (memcmp(tag,"\x40\x6f\x80",3) != 0))
   452          ThrowPDBReaderException(CorruptImageError,CorruptImage,image);
   453        if ((offset-TellBlob(image)) == 6)
   454          {
   455            (void) ReadBlobByte(image);
   456            (void) ReadBlobByte(image);
   457          }
   458      }
   459    /*
   460      Read image header.
   461    */
   462    (void) ReadBlob(image,32,pdb_image.name);
   463    pdb_image.version=ReadBlobByte(image);
   464    pdb_image.type=ReadBlobByte(image);
   465    pdb_image.reserved_1=ReadBlobMSBLong(image);
   466    pdb_image.note=ReadBlobMSBLong(image);
   467    pdb_image.x_last=ReadBlobMSBShort(image);
   468    pdb_image.y_last=ReadBlobMSBShort(image);
   469    pdb_image.reserved_2=ReadBlobMSBLong(image);
   470    pdb_image.x_anchor=ReadBlobMSBShort(image);
   471    pdb_image.y_anchor=ReadBlobMSBShort(image);
   472    pdb_image.width=ReadBlobMSBShort(image);
   473    pdb_image.height=ReadBlobMSBShort(image);
   474    if (image->logging)
   475      LogPDPImage(&pdb_image);
   476    /*
   477      Initialize image structure.
   478    */
   479    image->columns=pdb_image.width;
   480    image->rows=pdb_image.height;
   481    image->depth=8;
   482    image->storage_class=PseudoClass;
   483    bits_per_pixel=pdb_image.type == 0 ? 2 : pdb_image.type == 2 ? 4 : 1;
   484    if (!AllocateImageColormap(image,1 << bits_per_pixel))
   485      ThrowPDBReaderException(ResourceLimitError,MemoryAllocationFailed,image);
   486    if (image_info->ping)
   487      {
   488        CloseBlob(image);
   489        return(image);
   490      }
   491
   492    if (CheckImagePixelLimits(image, exception) != MagickPass)
   493      ThrowPDBReaderException(ResourceLimitError,ImagePixelLimitExceeded,image);
   494
   495    packets=MagickArraySize(MagickArraySize(bits_per_pixel,image->columns)/8,
   496                            image->rows);
   497    pixels=MagickAllocateMemory(unsigned char *,packets + (packets != 0 ? 256 : 0));
   498    if (pixels == (unsigned char *) NULL)
   499      ThrowPDBReaderException(ResourceLimitWarning,MemoryAllocationFailed,image);
   500    switch (pdb_image.version)
   501    {
   502      case 0:
   503      {
   504        image->compression=NoCompression;
   505        if (ReadBlob(image,packets,(char *) pixels) != packets)
   506          {
   507            MagickFreeMemory(pixels);
   508            ThrowReaderException(CorruptImageError,UnexpectedEndOfFile,image);
   509          }
   510        break;
   511      }
   512      case 1:
   513      {
   514        image->compression=RLECompression;
   515        if (DecodeImage(image,pixels,packets) == MagickFail)
   516          ThrowPDBReaderException(CorruptImageError,UnexpectedEndOfFile,image);
   517        break;
   518      }
   519      default:
   520        {
   521          ThrowPDBReaderException(CorruptImageError,UnrecognizedImageCompression,image);
   522        }
   523    }
   524    p=pixels;
   525    switch (bits_per_pixel)
   526    {
   527      case 1:
   528      {
   529        int
   530          bit;
   531
   532        /*
   533          Read 1-bit PDB image.
   534        */
   535        for (y=0; y < image->rows; y++)
   536        {
   537          q=SetImagePixels(image,0,y,image->columns,1);
   538          if (q == (PixelPacket *) NULL)
   539            break;
   540          indexes=AccessMutableIndexes(image);
   541          bit=0;
   542          for (x=0; x < image->columns; x++)
   543          {
   544            index=(*p & (0x80U >> bit) ? 0x00U : 0x01U);
   545            indexes[x]=index;
   546            *q++=image->colormap[index];
   547            bit++;
   548            if (bit == 8)
   549              {
   550                p++;
   551                bit=0;
   552              }
   553          }
   554          if (!SyncImagePixels(image))
   555            break;
   556          if (QuantumTick(y,image->rows))
   557            if (!MagickMonitorFormatted(y,image->rows,exception,LoadImageText,
   558                                        image->filename,
   559                                        image->columns,image->rows))
   560              break;
   561        }
   562        break;
   563      }
   564      case 2:
   565      {
   566        /*
   567          Read 2-bit PDB image.
   568        */
   569        unsigned int
   570          shift;
   571
   572        for (y=0; y < image->rows; y++)
   573        {
   574          q=SetImagePixels(image,0,y,image->columns,1);
   575          if (q == (PixelPacket *) NULL)
   576            break;
   577          indexes=AccessMutableIndexes(image);
   578          shift = 8;
   579          for (x=0; x < image->columns; x++)
   580            {
   581              shift -= 2;
   582              index=(IndexPacket) (3-((*p >> shift) & 0x03));
   583              VerifyColormapIndex(image,index);
   584              indexes[x]=index;
   585              if (shift == 0)
   586                {
   587                  shift = 8;
   588                  p++;
   589                }
   590            }
   591          if (!SyncImagePixels(image))
   592            break;
   593          if (QuantumTick(y,image->rows))
   594            if (!MagickMonitorFormatted(y,image->rows,exception,LoadImageText,
   595                                        image->filename,
   596                                        image->columns,image->rows))
   597              break;
   598        }
   599        break;
   600      }
   601      case 4:
   602      {
   603        /*
   604          Read 4-bit PDB image.
   605        */
   606        unsigned int
   607          shift;
   608
   609        for (y=0; y < image->rows; y++)
   610        {
   611          q=SetImagePixels(image,0,y,image->columns,1);
   612          if (q == (PixelPacket *) NULL)
   613            break;
   614          indexes=AccessMutableIndexes(image);
   615          shift = 8;
   616          for (x=0; x < image->columns; x++)
   617          {
   618            shift -= 4;
   619            index=(IndexPacket) (15-((*p >> shift) & 0x0f));
   620            VerifyColormapIndex(image,index);
   621            indexes[x]=index;
   622            *q++=image->colormap[index];
   623            if (shift == 0)
   624              {
   625                shift = 8;
   626                p++;
   627              }
   628          }
   629          if (!SyncImagePixels(image))
   630            break;
   631          if (QuantumTick(y,image->rows))
   632            if (!MagickMonitorFormatted(y,image->rows,exception,LoadImageText,
   633                                        image->filename,
   634                                        image->columns,image->rows))
   635              break;
   636        }
   637        break;
   638      }
   639      default:
   640        {
   641          ThrowPDBReaderException(CorruptImageError,ImproperImageHeader,image);
   642        }
   643    }
   644    MagickFreeMemory(pixels);
   645    if (EOFBlob(image))
   646      ThrowException(exception,CorruptImageError,UnexpectedEndOfFile,
   647        image->filename);
   648    if ((offset-TellBlob(image)) == 0)
   649      {
   650        char
   651          *comment;
   652
   653        int
   654          c;
   655
   656        register char
   657          *p;
   658
   659        size_t
   660          length;
   661
   662        /*
   663          Read comment.
   664        */
   665        c=ReadBlobByte(image);
   666        length=MaxTextExtent;
   667        comment=MagickAllocateMemory(char *,length+1);
   668        p=comment;
   669        p[0]='\0';
   670        if (comment != (char *) NULL)
   671          for ( ; c != EOF; p++)
   672          {
   673            if ((size_t) (p-comment) >= length)
   674              {
   675                length<<=1;
   676                length+=MaxTextExtent;
   677                MagickReallocMemory(char *,comment,length+1);
   678                if (comment == (char *) NULL)
   679                  break;
   680                p=comment+strlen(comment);
   681              }
   682            *p=c;
   683            *(p+1)='\0';
   684            c=ReadBlobByte(image);
   685          }
   686        if (comment == (char *) NULL)
   687          ThrowPDBReaderException(ResourceLimitError,MemoryAllocationFailed,image);
   688        (void) SetImageAttribute(image,"comment",comment);
   689        MagickFreeMemory(comment);
   690      }
   691    CloseBlob(image);
   692    return(image);
   693  }
